"""Selection persistence, routes, actual selected endpoint and fail-closed resolution."""
import pathlib, subprocess, tempfile
root=pathlib.Path(__file__).resolve().parents[2]
stubs={
'android/util/Base64.java':'''package android.util;public class Base64 {public static final int URL_SAFE=8,NO_WRAP=2,NO_PADDING=1;public static String encodeToString(byte[] b,int flags){return java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(b);}}''',
'org/telegram/messenger/MessagesController.java':'''package org.telegram.messenger;import java.util.*;public class MessagesController {static Settings s=new Settings();public static Settings getGlobalMainSettings(){return s;}public static class Settings {Map<String,String> m=new HashMap<>();public String getString(String k,String d){return m.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return d;}public Settings edit(){return this;}public Settings putString(String k,String v){m.put(k,v);return this;}public void apply(){}}}''',
'org/telegram/utils/proxy/TorProxyController.java':'''package org.telegram.utils.proxy;public class TorProxyController{public static boolean tor;public static boolean isEnabled(){return tor;}}''',
'org/telegram/ui/web/AmpResolver.java':'''package org.telegram.ui.web;import java.util.*;import java.io.*;public class AmpResolver {public static int queries;public static String last;public static boolean fail,change,privateAnswer;public static byte[] fetchDnsMessage(String url)throws IOException{last=url;return reply(Base64.getUrlDecoder().decode(url.substring(url.indexOf("?dns=")+5)));}public static byte[] fetchDnsTls(String host,byte[] query)throws IOException{last=host;return reply(query);}static byte[] reply(byte[] q)throws IOException{queries++;if(fail)throw new IOException();if(change)org.telegram.utils.proxy.DnsConfig.select("");byte[] r=Arrays.copyOf(q,q.length+16);r[2]=(byte)0x81;r[3]=(byte)0x80;r[7]=1;byte[] a={(byte)0xc0,12,0,1,0,1,0,0,0,60,0,4,93,(byte)184,(byte)216,34};if(privateAnswer)a[12]=10;System.arraycopy(a,0,r,q.length,16);return r;}}''',
'Check.java':'''import org.telegram.utils.proxy.*;import org.telegram.ui.web.*;public class Check {static void ck(boolean b){if(!b)throw new AssertionError();}static void fails()throws Exception{try{DnsConfig.resolve("example.com");throw new AssertionError();}catch(java.io.IOException expected){}}public static void main(String[]args)throws Exception{ck(DnsConfig.selected().isEmpty());DnsConfig.select("https://dns.google/dns-query");ck(DnsConfig.resolve("example.com").length==1&&AmpResolver.last.startsWith("https://dns.google/"));ck(DnsConfig.resolve("example.com").length==1 && AmpResolver.queries==1);DnsConfig.select(DnsConfig.selected());AmpResolver.fail=true;fails();ck(DnsConfig.selected().equals("https://dns.google/dns-query"));AmpResolver.fail=false;AmpResolver.privateAnswer=true;fails();AmpResolver.privateAnswer=false;TorProxyController.tor=true;fails();TorProxyController.tor=false;DnsConfig.select("tls://dns.quad9.net:853");ck(DnsConfig.resolve("example.com").length==1&&AmpResolver.last.equals("dns.quad9.net"));DnsConfig.select(DnsConfig.selected());AmpResolver.change=true;fails();ck(DnsConfig.selected().isEmpty());System.out.println("DNS selection: endpoint, DoT, persistence, failure without fallback, private answers, Tor priority and selection race passed");}}'''}
with tempfile.TemporaryDirectory() as tmp:
 paths=[]
 for name,text in stubs.items():
  p=pathlib.Path(tmp,name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text);paths.append(str(p))
 for name in ['utils/proxy/DnsConfig.java','utils/proxy/DnsAnswerCache.java','utils/proxy/DnsWire.java','utils/proxy/DnsProbe.java','ui/web/AmpUrls.java']:
  paths.append(str(root/'TMessagesProj/src/main/java/org/telegram'/name))
 subprocess.run(['javac','-encoding','UTF-8','-d',tmp,*paths],check=True)
 subprocess.run(['java','-cp',tmp,'Check'],check=True)
